// src/server.ts
function createServer() {
  const server3 = new McpServer(
    {
      name: "prudent-mcp",
      // Single-sourced from package.json — the two drifted before.
      version: package_default.version
    },
    {
      // Written in the library's own words (src/language.ts, eval I17): a model repeats what it is told to the person it is
      // answering. Tool names are the one exception, since they have to be named. The rules about the EDGE of the library
      // (amended text, versions, an instrument not held, a placeholder, a weak match) are not here: each response carries
      // the note that applies, at the point it applies, written to be repeated as it stands. About 300 tokens, held there
      // by tests/instructions.test.ts.
      instructions: 'Prudent: EU regulation and supervisory practice for internal ratings-based (IRB) credit risk (the CRR, EBA guidelines and the ECB guide to internal models), with a playbook per topic.\nFor any substantive question, call brief first: it returns the playbook that answers it and the provisions that matter. Expand with playbook (topics lists them); open specific provisions with search, get or cite; use related for neighbouring provisions and sources for what the library covers and what is changing.\nWhen you answer: cite provisions by their official citation (e.g. "EBA/GL/2017/16 para 28", "Art. 179(1)(d) CRR"), never by internal identifiers, and do not describe the tools. Keep law, EBA guidelines, ECB supervisory expectations and market practice distinct, as the playbook labels them. Repeat each note a response carries: when a provision is amended or about to be, say so with the date and what changes. When the question turns on an instrument the library does not hold, name it and answer from general knowledge, marked as such.'
    }
  );
  registerBriefTool(server3);
  registerPlaybookTool(server3);
  registerTopicsTool(server3);
  registerSearchTool(server3);
  registerGetTool(server3);
  registerCiteTool(server3);
  registerRelatedTool(server3);
  registerSourcesTool(server3);
  registerResources(server3);
  registerPrompts(server3);
  return server3;
}
